// Generated native helpers; reading fields follow the canonical request controls.
#pragma once
namespace duckdb {
inline void RegisterRequestHelpers(ExtensionLoader &loader) {
    RegisterPortableMacro(loader, "CREATE MACRO thinkthen_reading(\"attempts\" := NULL, \"batch\" := NULL, \"context\" := NULL, \"context_field\" := NULL, \"deadline_ms\" := NULL, \"details\" := NULL, \"examples\" := NULL, \"examples_field\" := NULL, \"field\" := NULL, \"files_only\" := NULL, \"max_requests_total\" := NULL, \"mode\" := NULL, \"model\" := NULL, \"none\" := NULL, \"options_field\" := NULL, \"relation_threshold\" := NULL, \"seed_spans\" := NULL, \"seed_spans_field\" := NULL, \"snippet_pieces\" := NULL, \"stage_context\" := NULL, \"threshold\" := NULL, \"top\" := NULL, \"context_schema\" := NULL) AS {'attempts':\"attempts\", 'batch':\"batch\", 'context':\"context\", 'context_field':\"context_field\", 'deadline_ms':\"deadline_ms\", 'details':\"details\", 'examples':\"examples\", 'examples_field':\"examples_field\", 'field':\"field\", 'files_only':\"files_only\", 'max_requests_total':\"max_requests_total\", 'mode':\"mode\", 'model':\"model\", 'none':\"none\", 'options_field':\"options_field\", 'relation_threshold':\"relation_threshold\", 'seed_spans':\"seed_spans\", 'seed_spans_field':\"seed_spans_field\", 'snippet_pieces':\"snippet_pieces\", 'stage_context':\"stage_context\", 'threshold':\"threshold\", 'top':\"top\", 'context_schema':\"context_schema\"}", "Construct named native request reading controls without executing a call.");
    RegisterPortableMacro(loader, "CREATE MACRO thinkthen_source(\"paths\", \"unit\" := 'line', \"window\" := NULL, \"format\" := NULL, \"media\" := 'text') AS {'paths':\"paths\", 'unit':\"unit\", 'window':\"window\", 'format':\"format\", 'media':\"media\"}", "Select explicit local source paths, physical reading units, logical framing and media for an authorized call.");
    RegisterPortableMacro(loader, "CREATE MACRO thinkthen_location(\"file\", \"first_line\" := NULL, \"last_line\" := NULL) AS {'file':\"file\", 'first_line':\"first_line\", 'last_line':\"last_line\"}", "Retain physical source identity and optional line coordinates without adding model evidence.");
    RegisterPortableMacro(loader, "CREATE MACRO thinkthen_record(\"text\" := NULL, \"json\" := NULL, \"document\" := NULL, \"context\" := NULL, \"options\" := NULL, \"examples\" := NULL, \"seed_spans\" := NULL, \"images\" := NULL, \"source\" := NULL) AS {'text':\"text\", 'json':\"json\", 'document':\"document\", 'context':\"context\", 'options':\"options\", 'examples':\"examples\", 'seed_spans':\"seed_spans\", 'images':\"images\", 'source':\"source\"}", "Construct one native original with its context, shortlist, recognition controls, images and source.");
}
} // namespace duckdb
